import json
import os
import shutil

from pyspark.sql import functions as F
from delta.tables import DeltaTable


def layout(path):
    # One row per pickup day: the table's data files and their trips, from the log. Don't change this.
    files = {}
    log = path + "/_delta_log/"
    for name in sorted(f for f in os.listdir(log) if f.endswith(".json")):
        with open(log + name) as f:
            for line in f:
                action = json.loads(line)
                if "add" in action:
                    add = action["add"]
                    files[add["path"]] = (add["partitionValues"].get("pickup_date"), json.loads(add["stats"])["numRecords"])
                if "remove" in action:
                    files.pop(action["remove"]["path"], None)
    by_day = {}
    for day, rows in files.values():
        by_day.setdefault(day, []).append(rows)
    return spark.createDataFrame(
        [(day, len(rows), sum(rows)) for day, rows in by_day.items()],
        "pickup_date STRING, files INT, trips INT",
    )


def write_table(trips, path):
    # Write the trips partitioned by the day they were picked up.
    trips.write.format("delta").save(path)


