def solve(trips):
    path = "/tmp/taxi/trips_by_day"
    shutil.rmtree(path, ignore_errors=True)  # start from an empty folder on every run
    feed = trips.repartition(3)  # the feed hands the trips over in three parts
    write_table(feed, path)
    compact(path)
    return layout(path)
